CREATE FUNCTION public._sync_boss(_uid uuid,_bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bosses; v numeric:=0; lv jsonb; total_day numeric; tz text; BEGIN SELECT * INTO b FROM public.bosses WHERE id=_bid; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.season_entries WHERE user_id=_uid AND season_id=b.season_id) THEN RETURN; END IF; SELECT timezone INTO tz FROM public.profiles WHERE id=_uid; PERFORM pg_advisory_xact_lock(hashtext(_uid::text||_bid::text)); INSERT INTO public.boss_entries(boss_id,user_id) VALUES(_bid,_uid) ON CONFLICT DO NOTHING;
IF b.metric='reps' THEN IF b.exercise_key='pullups' THEN SELECT greatest(coalesce((SELECT sum(ls.reps) FROM public.lift_sets ls JOIN public.lift_exercises ex ON ex.id=ls.exercise_id WHERE ls.user_id=_uid AND ex.key='pullups' AND ls.day=g.day),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid AND (created_at AT TIME ZONE tz)::date=g.day),0)) INTO total_day FROM (SELECT day FROM public.lift_sets WHERE user_id=_uid AND day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date UNION SELECT (created_at AT TIME ZONE tz)::date FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid) g ORDER BY 1 DESC LIMIT 1; v:=coalesce(total_day,0); ELSE SELECT greatest(coalesce((SELECT sum(ls.reps) FROM public.lift_sets ls JOIN public.lift_exercises ex ON ex.id=ls.exercise_id WHERE ls.user_id=_uid AND ex.equipment='dumbbell' AND ls.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid),0)) INTO v; END IF;
ELSIF b.metric='km' THEN SELECT greatest(coalesce((SELECT sum(CASE WHEN h.unit='mi' THEN ci.value*1.609344 ELSE ci.value END) FROM public.checkins ci JOIN public.user_habits h ON h.id=ci.user_habit_id JOIN public.habit_templates ht ON ht.id=h.template_id WHERE ci.user_id=_uid AND h.season_id=b.season_id AND ht.key=b.exercise_key AND ci.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid),0)) INTO v;
ELSIF b.metric='days' THEN IF b.exercise_key='completion' THEN SELECT count(*) INTO v FROM public.daily_scores WHERE user_id=_uid AND season_id=b.season_id AND completion>=1 AND day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date; ELSE SELECT count(DISTINCT ci.day) INTO v FROM public.checkins ci JOIN public.user_habits h ON h.id=ci.user_habit_id JOIN public.habit_templates ht ON ht.id=h.template_id WHERE ci.user_id=_uid AND h.season_id=b.season_id AND ht.key=b.exercise_key AND ci.value>=h.target AND ci.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date; END IF;
ELSIF b.metric='posts' THEN SELECT count(*) INTO v FROM public.posts WHERE user_id=_uid AND season_id=b.season_id AND NOT hidden AND type IN ('thought','win') AND char_length(body)>=20 AND stats->>'boss_lesson'='true' AND created_at BETWEEN b.starts_at AND b.ends_at;
ELSE SELECT least(40,coalesce(sum(amount) FILTER(WHERE part='burpees'),0))+least(40,coalesce(sum(amount) FILTER(WHERE part='pullups'),0)) INTO v FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid; END IF;
UPDATE public.boss_entries SET progress=v WHERE boss_id=_bid AND user_id=_uid; SELECT l INTO lv FROM public.boss_entries e CROSS JOIN LATERAL jsonb_array_elements(b.levels) l WHERE e.boss_id=_bid AND e.user_id=_uid AND l->>'key'=e.level;
IF v>=(lv->>'target')::numeric AND now() BETWEEN b.starts_at AND b.ends_at THEN INSERT INTO public.bonus_points(user_id,season_id,boss_id,level,points) VALUES(_uid,b.season_id,_bid,lv->>'key',(lv->>'bonus')::int) ON CONFLICT DO NOTHING; UPDATE public.boss_entries SET completed_at=coalesce(completed_at,now()) WHERE boss_id=_bid AND user_id=_uid; INSERT INTO public.badges(user_id,season_id,key) VALUES(_uid,b.season_id,'boss_ko') ON CONFLICT DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public._sync_boss(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.boss_action(_boss_id uuid,_action text,_amount numeric DEFAULT 5,_level text DEFAULT 'pro',_part text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); b public.bosses; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; SELECT * INTO b FROM public.bosses WHERE id=_boss_id; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.season_entries WHERE user_id=uid AND season_id=b.season_id) OR now() NOT BETWEEN b.starts_at AND b.ends_at THEN RAISE EXCEPTION 'boss_closed'; END IF; PERFORM pg_advisory_xact_lock(hashtext(uid::text||_boss_id::text)); INSERT INTO public.boss_entries(boss_id,user_id) VALUES(_boss_id,uid) ON CONFLICT DO NOTHING;
IF _action='hit' THEN IF _amount IS NULL OR _amount<=0 OR _amount>10000 OR b.metric IN ('days','posts') OR (b.metric='reps' AND _amount<>floor(_amount)) OR (b.metric='custom' AND (_part IS NULL OR _part NOT IN ('pullups','burpees') OR _amount<>floor(_amount))) THEN RAISE EXCEPTION 'invalid_hit'; END IF; INSERT INTO public.boss_hits(boss_id,user_id,amount,part) VALUES(_boss_id,uid,_amount,_part);
ELSIF _action='reset' THEN DELETE FROM public.boss_hits WHERE boss_id=_boss_id AND user_id=uid; UPDATE public.boss_entries SET completed_at=NULL WHERE boss_id=_boss_id AND user_id=uid;
ELSIF _action='level' THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.levels) l WHERE l->>'key'=_level) THEN RAISE EXCEPTION 'invalid_level'; END IF; UPDATE public.boss_entries SET level=_level,completed_at=NULL WHERE boss_id=_boss_id AND user_id=uid; ELSE RAISE EXCEPTION 'invalid_action'; END IF; PERFORM public._sync_boss(uid,_boss_id); END $$;
CREATE FUNCTION public.hit_boss(_boss_id uuid,_amount numeric DEFAULT 5,_part text DEFAULT NULL) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.boss_action(_boss_id,'hit',_amount,'pro',_part) $$;
CREATE FUNCTION public.reset_boss(_boss_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.boss_action(_boss_id,'reset') $$;
CREATE FUNCTION public.sync_boss_saved_data() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; b record; BEGIN uid:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END; FOR b IN SELECT id FROM public.bosses WHERE now() BETWEEN starts_at AND ends_at LOOP PERFORM public._sync_boss(uid,b.id); END LOOP; RETURN NULL; END $$;
CREATE TRIGGER lift_boss_sync AFTER INSERT OR UPDATE OR DELETE ON public.lift_sets FOR EACH ROW EXECUTE FUNCTION public.sync_boss_saved_data(); CREATE TRIGGER checkin_boss_sync AFTER INSERT OR UPDATE OR DELETE ON public.checkins FOR EACH ROW EXECUTE FUNCTION public.sync_boss_saved_data(); CREATE TRIGGER post_boss_sync AFTER INSERT OR UPDATE OR DELETE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.sync_boss_saved_data(); CREATE TRIGGER score_boss_sync AFTER INSERT OR UPDATE ON public.daily_scores FOR EACH ROW EXECUTE FUNCTION public.sync_boss_saved_data();
CREATE FUNCTION public.boss_overview(_season_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); b public.bosses; r jsonb; cc text; BEGIN IF uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.season_entries WHERE season_id=_season_id AND user_id=uid) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT country_code INTO cc FROM public.profiles WHERE id=uid; SELECT * INTO b FROM public.bosses WHERE season_id=_season_id AND now() BETWEEN starts_at AND ends_at ORDER BY week_no LIMIT 1; IF b.id IS NOT NULL THEN PERFORM public._sync_boss(uid,b.id); END IF; SELECT jsonb_build_object('boss',CASE WHEN b.id IS NOT NULL THEN to_jsonb(b) END,'entry',(SELECT to_jsonb(e) FROM public.boss_entries e WHERE boss_id=b.id AND user_id=uid),'awarded',coalesce((SELECT jsonb_agg(level) FROM public.bonus_points WHERE boss_id=b.id AND user_id=uid),'[]'::jsonb),'bonus',coalesce((SELECT sum(points) FROM public.bonus_points WHERE user_id=uid AND season_id=_season_id),0),'next',coalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.starts_at) FROM public.bosses n WHERE n.season_id=_season_id AND n.starts_at>now()),'[]'::jsonb),'country',cc,'community',coalesce((SELECT sum(e.progress) FROM public.boss_entries e JOIN public.profiles p ON p.id=e.user_id WHERE e.boss_id=b.id AND p.country_code=cc AND p.show_on_public_board),0),'community_target',50000,'leaders',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT p.display_name,p.handle,e.progress FROM public.boss_entries e JOIN public.profiles p ON p.id=e.user_id WHERE e.boss_id=b.id AND p.country_code=cc AND p.show_on_public_board ORDER BY e.progress DESC,p.handle LIMIT 5) x),'[]'::jsonb)) INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.boss_action(uuid,text,numeric,text,text),public.hit_boss(uuid,numeric,text),public.reset_boss(uuid),public.boss_overview(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.boss_action(uuid,text,numeric,text,text),public.hit_boss(uuid,numeric,text),public.reset_boss(uuid),public.boss_overview(uuid) TO authenticated;